{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "STATUS_A.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "A Liberação de engenharia está prevista para D40",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia está prevista para D42."
        },
        {
          "citacao": "o Design Freeze para D14",
          "motivo": "valor_divergente",
          "correto_seria": "O Design Freeze passa a D16."
        },
        {
          "citacao": "a disponibilidade do protótipo para D25",
          "motivo": "valor_divergente",
          "correto_seria": "A disponibilidade do protótipo passa a D27."
        },
        {
          "citacao": "O caminho crítico passa pela entrega da GearWorks em D20",
          "motivo": "premissa_alterada",
          "correto_seria": "O caminho crítico passa pela análise estrutural, compras e fabricação de D16 a D22 e montagem a partir de D22; a entrega da GearWorks em D20 tem 2 dias de folga."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "com 2 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MotorTech entrega o motor em D18, com 4 dias de folga."
        },
        {
          "citacao": "sem folga",
          "motivo": "valor_divergente",
          "correto_seria": "A GearWorks entrega o redutor em D20, com 2 dias de folga."
        },
        {
          "citacao": "com 3 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MetalForm entrega os componentes em D17, com 5 dias de folga."
        },
        {
          "citacao": "com 4 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A SensePro entrega o sensor em D16, com 6 dias de folga."
        },
        {
          "citacao": "com apenas 1 dia de folga",
          "motivo": "valor_divergente",
          "correto_seria": "O fornecedor da placa de controle e do chicote entrega em D19, com 3 dias de folga."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.ENGENHARIA",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a análise estrutural, de D10 a D14",
          "motivo": "valor_divergente",
          "correto_seria": "A análise estrutural ocorre de D10 a D16."
        },
        {
          "citacao": "Compras e fabricação ocorrem de D14 a D20",
          "motivo": "valor_divergente",
          "correto_seria": "Compras e fabricação ocorrem de D16 a D22."
        },
        {
          "citacao": "a montagem do protótipo, de D20 a D25",
          "motivo": "valor_divergente",
          "correto_seria": "A montagem do protótipo ocorre de D22 a D27."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.TESTES",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todos os testes começam em D25",
          "motivo": "valor_divergente",
          "correto_seria": "Todos os testes começam em D27."
        },
        {
          "citacao": "carga, 4 dias, até D29",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de carga dura 4 dias, até D31."
        },
        {
          "citacao": "térmico, 6 dias, até D31",
          "motivo": "valor_divergente",
          "correto_seria": "O teste térmico dura 6 dias, até D33."
        },
        {
          "citacao": "vida, 10 dias, até D35",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vida dura 10 dias, até D37."
        },
        {
          "citacao": "vedação, 3 dias, até D28",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vedação dura 3 dias, até D30."
        },
        {
          "citacao": "compatibilidade eletromagnética, 5 dias, até D30",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de compatibilidade eletromagnética dura 5 dias, até D32."
        },
        {
          "citacao": "deve ser concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação deve ser concluída em D37, ao fim do teste de vida."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "O orçamento total é de R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O custo total passa a R$ 152.600,00, incluindo 2 dias extras de gestão e instalação."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.OBSERVACOES",
      "rotulo": "SEM_AFIRMACAO",
      "informacoes": [],
      "observacao": "As avaliações sobre motivação e comunicação são opiniões; a próxima revisão por Ana não é verificável com as informações fornecidas."
    },
    {
      "trecho_id": "STATUS_B.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "está dentro do cronograma",
          "motivo": "premissa_alterada",
          "correto_seria": "A análise estrutural ganhou 2 dias, e a liberação passa de D40 para D42."
        },
        {
          "citacao": "sem risco no caminho crítico",
          "motivo": "certeza_sem_suporte",
          "correto_seria": "A informação fornecida não permite afirmar que não há riscos no caminho crítico."
        },
        {
          "citacao": "continua prevista para o fim da sexta semana",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia passa a D42, no início da sétima semana."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.SUPRIMENTOS",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "As datas de entrega permanecem na terceira semana; a folga atual da eletrônica é de 3 dias."
    },
    {
      "trecho_id": "STATUS_B.ENGENHARIA",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "sem pendências previstas",
          "motivo": "premissa_alterada",
          "correto_seria": "A malha do suporte do redutor precisa ser refinada, e a análise estrutural passa a terminar em D16."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.TESTES",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "O protótipo fica pronto em D27, no fim da quarta semana; a validação termina em D37, no início da sexta semana."
    },
    {
      "trecho_id": "STATUS_B.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "sem desvios em relação ao total aprovado de R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O total passa a R$ 152.600,00, R$ 600,00 acima dos R$ 152.000,00."
        },
        {
          "citacao": "nem de gestão",
          "motivo": "valor_divergente",
          "correto_seria": "Há 2 dias extras de gestão; não há dias extras de laboratório."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.OBSERVACOES",
      "rotulo": "SEM_AFIRMACAO",
      "informacoes": [],
      "observacao": "A avaliação sobre o clima é uma opinião; a informação restante refere-se ao projeto Beta."
    }
  ]
}
